export type ParsedSettleChannelInstruction<
  TProgram extends string = typeof BUCKSPAY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    /** Pays the rent of the channels it creates. */
    payer: TAccountMetas[0]
    rewardMint: TAccountMetas[1]
    poolLedger: TAccountMetas[2]
    poolEscrow: TAccountMetas[3]
    feeAccount: TAccountMetas[4]
    tree: TAccountMetas[5]
    mint: TAccountMetas[6]
    instructions: TAccountMetas[7]
    tokenProgram: TAccountMetas[8]
    systemProgram: TAccountMetas[9]
  }
  data: SettleChannelInstructionData
}

export function parseSettleChannelInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleChannelInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 10,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      rewardMint: getNextAccount(),
      poolLedger: getNextAccount(),
      poolEscrow: getNextAccount(),
      feeAccount: getNextAccount(),
      tree: getNextAccount(),
      mint: getNextAccount(),
      instructions: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSettleChannelInstructionDataDecoder().decode(instruction.data),
  }
}
